#include <iostream>
#include <list>
#include <string>
#include <unordered_map>
#include <utility>

// The solution file defines this struct identically; the layout must match.
struct LruCache
{
    int capacity;
    std::list<std::pair<int, int>> order;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> index;
};

int Get(LruCache& cache, int key);
void Put(LruCache& cache, int key, int value);

int main()
{
    int capacity, n;
    while (std::cin >> capacity >> n)
    {
        LruCache cache;
        cache.capacity = capacity;
        bool first = true;
        for (int i = 0; i < n; i++)
        {
            std::string op;
            std::cin >> op;
            if (op == "put")
            {
                int k, v;
                std::cin >> k >> v;
                Put(cache, k, v);
            }
            else
            {
                int k;
                std::cin >> k;
                if (!first) { std::cout << " "; }
                first = false;
                std::cout << Get(cache, k);
            }
        }
        std::cout << "\n";
    }
    return 0;
}

