"""Random operation sequences over a small key space so evictions, hits,
misses and updates all happen; the final operation is always a get."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    capacity = rng.randint(1, 4)
    ops = []
    for _ in range(rng.randint(8, 20)):
        key = rng.randint(1, 6)
        if rng.random() < 0.5:
            ops.append("put %d %d" % (key, rng.randint(1, 99)))
        else:
            ops.append("get %d" % key)
    ops.append("get %d" % rng.randint(1, 6))
    return {"name": "capacity %d, %d operations #%d" % (capacity, len(ops), index),
            "stdin": "%d %d\n%s\n" % (capacity, len(ops), "\n".join(ops))}
